import {C,$,esc,toast,save,on,modal,methodMarkup,bindMethods,wait} from './studio-ui.js';
import {makeTopic,budget,selectNovel,uid,clone,taskSnapshot} from './workflow-store.js';
export function creationPage(){const s=C.s;return `<div class="page-heading"><div><p class="eyebrow">开始创作</p><h1>从一个想法，或一篇小说开始</h1><p>先确定短片规格，再展开你的故事。</p></div><span class="demo-label">交互原型 · AI 为示例</span></div><section class="panel" id="creation-setup"><div class="setup-grid"><label class="field">创作类型<select id="creation-mode"><option value="idea" ${s.mode==='idea'?'selected':''}>一句话 → 短片</option><option value="novel" ${s.mode==='novel'?'selected':''}>小说 / 故事 → 短片</option></select></label><label class="field">视觉风格<select id="creation-style">${s.styles.map((x,i)=>`<option value="${i}" ${i===s.styleIndex?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">目标时长<select id="creation-duration">${[30,60,90].map(n=>`<option value="${n}" ${n===s.duration?'selected':''}>${n} 秒</option>`).join('')}</select></label><label class="field">画幅<select id="creation-aspect">${['9:16','16:9','1:1'].map(x=>`<option ${s.aspect===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field input-main">${s.mode==='idea'?'一句话创意':'小说 / 故事正文'}<textarea id="creation-input" class="${s.mode==='novel'?'novel-import':''}" placeholder="${s.mode==='idea'?'写下人物、目标或你想表达的一句话':'粘贴小说或故事，系统将按目标时长改编剧本'}">${esc(s.mode==='idea'?s.idea:s.novelInput)}</textarea></label>${methodMarkup(s.mode==='idea'?'writingMethod':'scriptMethod')}<div class="section-end"><p class="helper">${s.mode==='idea'?`生成 3 个不同剧情方向，小说篇幅参考 ${budget(s.duration).min}–${budget(s.duration).max} 字。`:'保留原文，按短片时长提炼剧情；生成剧本后自动质检。'}</p>${s.mode==='idea'?'<button class="button primary" id="generate-topics">生成三个选题</button>':'<a class="button primary" id="import-novel" href="./script.html" data-nav="script">生成剧本 →</a>'}</div></section>${s.mode==='idea'?`<section id="topic-zone"><div class="panel-header"><h2>小说选题</h2><span class="helper">${s.topics.length?'点击卡片，打开全文与 AI 修改':'生成后在此选择一个方向'}</span></div><div class="topic-grid">${s.topics.map((t,i)=>`<button class="topic-card" data-topic="${t.id}"><span class="eyebrow">方向 ${i+1} · ${t.targetDuration} 秒</span><h3>${esc(t.title)}</h3><p>${esc(t.logline)}</p><span class="card-tail">${s.selectedNovel?.id===t.id?'已选定':'查看小说'} ↗</span></button>`).join('')||'<div class="empty-inline">还没有选题。先输入创意，再让 AI 提供三个方向。</div>'}</div>${s.topics.length?`<div class="new-topic"><label class="field">换一个方向试试<input type="text" id="new-topic-request" placeholder="例如：不要重逢，改成带悬念的误会" value="${esc(s.topicRequest)}"></label><button class="button" id="add-topic">生成新选题</button></div>`:''}</section>`:''}`;}
export function bindCreation(){const s=C.s;bindMethods();$('creation-mode').onchange=e=>{s.mode=e.target.value;save();C.render()};$('creation-input').oninput=e=>{s[s.mode==='idea'?'idea':'novelInput']=e.target.value;save()};for(const[id,key]of [['creation-duration','duration'],['creation-aspect','aspect'],['creation-style','styleIndex']])$(id).onchange=e=>{s[key]=key==='aspect'?e.target.value:+e.target.value;if(key==='styleIndex')s.styleVersion++;else{s.final=null;s.scriptReport=null;}if(s.shots.length){s.boardConfirmed=0;s.shots.forEach(sh=>{sh.videoStale=!!sh.video;sh.assets.forEach(a=>a.confirmed=false)});}save();C.render();if(s.topics.length)toast('新参数用于新生成的选题；已有选题保留原时长标签')};on('generate-topics',async()=>{if(!s.idea.trim()){toast('请先填写一句话创意');return}const button=$('generate-topics');button.disabled=true;button.textContent='生成选题中…';const snap=clone(s);await wait(400);const topics=[0,1,2].map(i=>makeTopic(snap,i));s.topicHistory??=[];if(s.topics.length)s.topicHistory.push(clone(s.topics));s.topics=topics;save();C.render();toast('已提供三个不同剧情方向（示例）')});on('add-topic',async()=>{s.topicRequest=$('new-topic-request').value;if(!s.topicRequest.trim()){toast('请描述新的剧情方向');return}$('add-topic').disabled=true;await wait(300);s.topics.push(makeTopic(s,s.topics.length,s.topicRequest));save();C.render()});if($('import-novel'))$('import-novel').onclick=e=>{if(!s.novelInput.trim()){e.preventDefault();toast('请先粘贴小说或故事正文');return}selectNovel(s,{id:uid('import'),title:'小说改编短片',text:s.novelInput,version:1});if(!save())e.preventDefault()};document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>openNovel(b.dataset.topic));}
function openNovel(id){const s=C.s,t=s.topics.find(x=>x.id===id);const b=budget(t.targetDuration);const d=modal(t.title,`<div class="novel-layout" id="novel-detail"><section><div class="panel-header"><span class="pill">小说 v${t.version}</span><span class="helper">${t.targetDuration} 秒 · 参考 ${b.min}–${b.max} 字</span></div><label class="field">小说全文<textarea id="novel-text">${esc(t.text)}</textarea></label><p id="novel-count" class="helper">${t.text.length} 字；可人工编辑，AI 修改保留旧版本。</p>${methodMarkup('scriptMethod')}<details><summary>历史版本（${t.versions.length}）</summary>${t.versions.map(v=>`<p class="helper">v${v.version}</p><p>${esc(v.text)}</p>`).join('')}</details></section><section class="novel-chat"><h3>与 AI 调整这篇小说</h3><div class="novel-messages">${t.messages.map(m=>`<p><strong>${m.role==='user'?'你':'AI'}：</strong>${esc(m.text)}</p>`).join('')||'<p class="helper">可以修改人物动机、剧情转折或结尾。也可以关闭详情，选择其他方向。</p>'}</div><label class="field">修改要求<textarea id="novel-request" placeholder="例如：结尾更温暖，减少人物数量"></textarea></label><button class="button" id="revise-novel">生成修改版</button><p class="helper">写作指令：${s.writingMethod.mode==='skill'?'所选 skill':'自定义提示词'}；返回时保留本次编辑。</p></section></div>`,`<a class="button primary" href="./script.html" data-nav="script" id="select-novel">选定并生成剧本 →</a>`);bindMethods(d);let manualVersion=false;$('novel-text').oninput=e=>{if(!manualVersion){t.versions.push({version:t.version,text:t.text});t.version++;manualVersion=true;}t.text=e.target.value;$('novel-count').textContent=`${t.text.length} 字；目标 ${t.targetDuration} 秒`;save()};on('revise-novel',async()=>{const request=$('novel-request').value.trim();if(!request){toast('请先填写修改要求');return}if(!t.text.trim()){toast('小说不能为空');return}const before=clone(t);$('revise-novel').disabled=true;$('revise-novel').textContent='生成修改版中…';await wait(400);t.versions.push({version:before.version,text:before.text});const parts=before.text.split('\n');parts[parts.length-1]=request.includes('悬念')||request.includes('反转')?'他正准备离开，却发现门后那张旧照片里，还有一个自己从未见过的人。':request.includes('温暖')?'老师递来干毛巾，轻声请他进屋。他笑着点头，终于说出了那句迟到的感谢。':'他停下脚步，把心里的话说清楚。对方认真听完，两个人一起作出了新的决定。';t.text=parts.join('\n');t.version++;t.messages.push({role:'user',text:request},{role:'ai',text:`已生成 v${t.version} 修改示例，可继续手动完善。`});t.snapshot=taskSnapshot(s,'novel',{instruction:request,previousText:before.text});save();d.close();openNovel(id)});$('select-novel').onclick=e=>{if(!t.text.trim()){e.preventDefault();toast('请先补充小说内容');return}if(t.targetDuration!==s.duration){e.preventDefault();toast('此选题按旧时长生成，请返回按新时长生成选题后再选定');return}selectNovel(s,t);if(!save())e.preventDefault()};}
